def build_context(chunks):
    return "\n\n".join(
        f"[{i}] (source={c['source']})\n{c['text']}"
        for i, c in enumerate(chunks, start=1)
    )

SYSTEM = (
    "Answer using ONLY the numbered context. Cite the id in brackets after "
    "each claim, e.g. [1]. If the context lacks the answer, say "
    "\"I don't have enough information to answer that.\""
)

chunks = [
    {"source": "refund_policy.md", "text": "Refunds are issued within 5 business days of return."},
    {"source": "shipping.md", "text": "Standard shipping takes 3-7 days."},
]
question = "How long do refunds take?"

context = build_context(chunks)
messages = [
    {"role": "system", "content": SYSTEM},
    {"role": "user", "content": f"Context:\n{context}\n\nQuestion: {question}"},
]
print(messages[1]["content"])

import re

REFUSAL = "I don't have enough information to answer that."

def verify_citations(answer, valid_ids):
    cited = {int(m) for m in re.findall(r"\[(\d+)\]", answer)}
    return cited.issubset(valid_ids) and bool(cited)

def grounded_answer(question, chunks, llm):
    if not chunks:
        return REFUSAL                     # nothing retrieved
    valid_ids = set(range(1, len(chunks) + 1))
    answer = llm(question)
    if not verify_citations(answer, valid_ids):
        return REFUSAL                     # phantom citation or none at all
    return answer

# fake LLM: returns a grounded answer, or one citing a phantom [9]
def good_llm(_):  return "Refunds take 5 business days [1]."
def bad_llm(_):   return "Refunds take 5 business days [1], up to 30 [9]."

chunks = [{"source": "refund_policy.md", "text": "...5 business days..."}]
print(grounded_answer("How long?", chunks, good_llm))
print(grounded_answer("How long?", chunks, bad_llm))
print(grounded_answer("How long?", [], good_llm))

