import re

REFUSAL = "I don't have enough information to answer that."

def enforce_grounding(answer: str, valid_ids: set[int]) -> str:
    cited = {int(m) for m in re.findall(r"\[(\d+)\]", answer)}
    if cited and cited.issubset(valid_ids):   # cited something, all resolve
        return answer
    return REFUSAL

if __name__ == "__main__":
    valid = {1, 2, 3}
    print(enforce_grounding("Refunds take 5 days [1].", valid))
    print(enforce_grounding("Up to 30 days [7].", valid))
    print(enforce_grounding("Definitely yes.", valid))

